const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
const context={structuredClone,console};vm.createContext(context);
vm.runInContext(fs.readFileSync('web/layer-tracks.js','utf8').replace(/export /g,''),context);
