const clone=x=>structuredClone(x), aid='asset_'+'2'.repeat(32), source=()=>clone(RECEIPTS[0].before);
const plan=(p=source(),at=.375,range={source_start:.625,source_end:1.875},options={})=>context.planAudioSourcePlacement(p,aid,at,range,options);
for(const [i,r] of RECEIPTS.entries())test('real public engine receipt '+i,()=>{const options=r.payload.track_id?{trackId:r.payload.track_id}:{};const p=plan(r.before,.375,undefined,options);assert.equal(p.issue,'');assert.equal(context.verifyAudioSourcePlacement(r.before,r.after,p).issue,'');});
for(const [label,fn] of Object.entries({duration:p=>p.assets[aid].duration=NaN,kind:p=>p.assets[aid].kind='video',ready:p=>p.assets[aid].status='failed',revision:p=>p.revision=-1,empty:p=>p.draft=null,future:p=>p.manual.layer_tracks={version:99,tracks:[]},error:p=>p.editor_sequence={error:'bad'},max:p=>p.editor_sequence.duration=86401}))test('admission '+label,()=>{const p=source();fn(p);assert.ok(plan(p).issue);});
for(const pair of [[NaN,1],[false,1],[-1,1],[0,4],[1,1.079999999],[2,1]])test('range refusal '+pair,()=>assert.ok(context.audioSourceRange(source().assets[aid],...pair).issue));
test('integer ns exact fit and no clamp',()=>{const p=source();p.editor_sequence.duration=.3;const result=plan(p,.1,{source_start:.2,source_end:.4});assert.equal(result.end,.3);assert.ok(plan(p,.100000001,{source_start:.2,source_end:.4}).issue);});
test('range canonicalized once',()=>{const r=context.audioSourceRange(source().assets[aid],.1234567891,.3234567891);assert.equal(r.source_start,.123456789);assert.equal(r.length,.2);});
for(const [label,fn] of Object.entries({extra:a=>a.manual.media_clips.push(clone(a.manual.media_clips[0])),clock:a=>a.manual.media_clips[0].source_start+=.1,gain:a=>a.manual.media_clips[0].volume_db=-1,role:a=>a.manual.media_clips[0].role='voice',unknown:a=>a.manual.media_clips[0].extra=true,settings:a=>a.settings.fps=60,asset:a=>a.assets[aid].duration=4,source:a=>a.sources.A.duration=4,revision:a=>a.revision+=1,draft:a=>a.draft.output_duration=2,controls:a=>a.manual.crop={x:.1}}))test('receipt rejects '+label,()=>{const r=clone(RECEIPTS[0]);fn(r.after);assert.ok(context.verifyAudioSourcePlacement(r.before,r.after,plan(r.before)).issue);});
test('receipt detects neutral allocator drift',()=>{const r=clone(RECEIPTS[5]);r.after.manual.layer_tracks.tracks.at(-1).audio.gain_db=-1;assert.ok(context.verifyAudioSourcePlacement(r.before,r.after,plan(r.before)).issue);});
const storage=()=>{const values=new Map();return {values,getItem:k=>values.has(k)?values.get(k):null,setItem:(k,v)=>values.set(k,v),removeItem:k=>values.delete(k)};};
test('marks save read clear and isolation',()=>{const p=source(),s=storage();assert.equal(context.readAudioSourceMarks(p,aid,s).state,'empty');context.saveAudioSourceMarks(p,aid,{source_start:.2,source_end:1},s);assert.equal(context.readAudioSourceMarks(p,aid,s).state,'saved');const other=clone(p);other.id+='copy';assert.equal(context.readAudioSourceMarks(other,aid,s).state,'empty');context.clearAudioSourceMarks(p,aid,s);assert.equal(s.values.size,0);});
test('marks metadata stale cache rename stable',()=>{const p=source(),s=storage();context.saveAudioSourceMarks(p,aid,{source_start:.2,source_end:1},s);p.assets[aid].url='new';p.assets[aid].name='new';assert.equal(context.readAudioSourceMarks(p,aid,s).state,'saved');p.assets[aid].duration=4;assert.equal(context.readAudioSourceMarks(p,aid,s).state,'stale');});
for(const raw of ['bad','x'.repeat(2049),'{}','[]'])test('marks corrupt '+raw.length,()=>{const s=storage(),p=source();context.saveAudioSourceMarks(p,aid,{source_start:0,source_end:1},s);s.values.set([...s.values.keys()][0],raw);assert.equal(context.readAudioSourceMarks(p,aid,s).state,'invalid');});
