for(const [label,change] of Object.entries({locked:p=>{p.manual.layer_tracks.version=2;p.manual.layer_tracks.tracks[0].locked=true;},wrong:p=>p.manual.layer_tracks.tracks[0].kind='visual',missing:p=>p.manual.layer_tracks.tracks=[]}))test('explicit destination '+label,()=>{const p=clone(RECEIPTS[1].before),tid=p.manual.layer_tracks.tracks[0].id;change(p);assert.ok(plan(p,.375,undefined,{trackId:tid}).issue);});
