test('marks extra fields invalid; namespace distinct',()=>{const p=source(),s=storage();context.saveAudioSourceMarks(p,aid,{source_start:0,source_end:1},s);const key=[...s.values.keys()][0];assert.ok(key.startsWith('cutroom.library-audio-source-marks.v1:'));const data=JSON.parse(s.values.get(key));data.extra=1;s.values.set(key,JSON.stringify(data));assert.equal(context.readAudioSourceMarks(p,aid,s).state,'invalid');});

