function capacityFixture(){const p=clone(RECEIPTS[5].before);p.manual.layer_tracks.protection_version=2;p.manual.layer_tracks.tracks=Array.from({length:4096},(_,i)=>({id:'track_'+(i+1).toString(16).padStart(32,'0'),kind:'visual',name:'Lane '+i,locked:false,audio:{gain_db:0,muted:false}}));return p;}
